import UIKit
import SwiftUI

struct ImageExporter {
    static func export(image: UIImage, withWatermark watermark: Bool) -> UIImage? {
        var finalImage = image

        if watermark {
            let overlay = WatermarkOverlay().snapshot()
            finalImage = UIImage.composite(overlay, over: image)
        }

        // Strip metadata
        return MetadataScrubber.scrubMetadata(from: finalImage)
    }
