// Services/Purchases/StoreManager.swift

import StoreKit
import SwiftUI

actor StoreManager {
    static let shared = StoreManager()

    func purchaseAuraPlus() async throws -> EntitlementSnapshot {
        let productIDs = ["com.app.aura.plus"]
        let products = try await Product.products(for: productIDs)
        guard let product = products.first else {
            throw StoreKitError.productNotFound
        }

        let result = try await product.purchase()
        switch result {
        case .success(let verification):
            let transaction = try checkVerified(verification)
            return await updateEntitlement(for: transaction)
        case .userCancelled, .pending:
            throw StoreKitError.userCancelledPurchase
        @unknown default:
            throw StoreKitError.unknownError
        }
    }

    func restorePurchases() async throws -> EntitlementSnapshot? {
        try await AppStore.sync()
        for await result in Transaction.updates {
            guard case .verified(let transaction) = result else { continue }
            return await updateEntitlement(for: transaction)
        }

        return nil
    }

    private func checkVerified<T>(_ result: VerificationResult<T>) throws -> T {
        switch result {
        case .unverified(_, let error): throw error
        case .verified(let safe):       return safe
        }
    }

    private func updateEntitlement(for transaction: Transaction) async -> EntitlementSnapshot {
        // Update entitlement logic here based on the transaction
        // For example, check if it's Aura+ and set isAuraPlus to true
        let snapshot = EntitlementSnapshot(isAuraPlus: true, unlockedPaletteTier: .auraPlusExpanded, capturedAt: Date())
        // Save this to persistent storage if needed
        return snapshot
    }
}
```

